VALUES('sirah_t4_p3',4,'Sirah','Pelajaran 3: Mubasysyirin bil Jannah',$sirahm3$[{"n":1,"title":"الزبير بن العوام","subtitle":"Latar belakang Zubair bin al-Awwam","icon":"🌿","cards":[{"q":"نام ڤنوه صحابة اين الزبير بن العوام.","a":"Nama sahabat ini ialah Zubair bin al-Awwam.","tip":"Nama sahabat ini ialah Zubair bin al-Awwam.","page":"73"},{"q":"ايبو الزبير اياله صفية بنت عبد المطلب.","a":"Ibu Zubair ialah Safiyyah binti Abdul Muttalib.","tip":"Ibu Zubair ialah Safiyyah binti Abdul Muttalib.","page":"73"},{"q":"صفية بنت عبد المطلب اياله ايبو ساودارا رسول الله ﷺ.","a":"Safiyyah binti Abdul Muttalib ialah ibu saudara Rasulullah ﷺ.","tip":"Safiyyah binti Abdul Muttalib ialah ibu saudara Rasulullah ﷺ.","page":"73"},{"q":"الزبير اداله انتارا صحابة رسول الله ﷺ.","a":"Zubair merupakan salah seorang sahabat Rasulullah ﷺ.","tip":"Zubair merupakan salah seorang sahabat Rasulullah ﷺ.","page":"73"}]},{"n":2,"title":"كإيمانن الزبير","subtitle":"Keislaman dan kesetiaan Zubair","icon":"🤲","cards":[{"q":"الزبير انتارا اورڠ يڠ اول مڠانوت اسلام.","a":"Zubair termasuk dalam golongan awal yang memeluk Islam.","tip":"Zubair termasuk dalam golongan awal yang memeluk Islam.","page":"73–74"},{"q":"الزبير تتڤ تڬوه دڠن عقيدة اسلام.","a":"Zubair tetap teguh beriman walaupun menghadapi cabaran.","tip":"Zubair tetap teguh beriman walaupun menghadapi cabaran.","page":"74"},{"q":"الزبير منجادي ڤمبلا رسول الله ﷺ.","a":"Zubair membantu dan mempertahankan perjuangan Rasulullah ﷺ.","tip":"Zubair membantu dan mempertahankan perjuangan Rasulullah ﷺ.","page":"74–75"},{"q":"الزبير ترماسوق دالم صحابة يڠ دجنجيكن شرݢ.","a":"Buku teks menyebut Zubair termasuk sahabat yang dijanjikan syurga.","tip":"Buku teks menyebut Zubair termasuk sahabat yang dijanjikan syurga.","page":"74"}]},{"n":3,"title":"كبرانين الزبير","subtitle":"Keberanian dan perjuangan Zubair","icon":"🛡️","cards":[{"q":"الزبير براني دالم ڤرچوڠن اسلام.","a":"Zubair dikenali kerana keberaniannya dalam perjuangan Islam.","tip":"Zubair dikenali kerana keberaniannya dalam perjuangan Islam.","page":"74–76"},{"q":"الزبير منرتاءي ڤڤرڠن برسام رسول الله ﷺ.","a":"Zubair turut bersama Rasulullah ﷺ dalam peperangan.","tip":"Zubair turut bersama Rasulullah ﷺ dalam peperangan.","page":"75–76"},{"q":"الزبير ممبنتو ممڤرتاهنكن اسلام.","a":"Antara sumbangan Zubair ialah mempertahankan Islam.","tip":"Antara sumbangan Zubair ialah mempertahankan Islam.","page":"75–76"},{"q":"صحابة براني تتڤ مماتوهي اراهن رسول الله ﷺ.","a":"Keberanian Zubair sentiasa dikaitkan dengan kesetiaan terhadap Rasulullah ﷺ.","tip":"Keberanian Zubair sentiasa dikaitkan dengan kesetiaan terhadap Rasulullah ﷺ.","page":"76"}]},{"n":4,"title":"تلادن الزبير","subtitle":"Sifat terpuji dan iktibar Zubair","icon":"⭐","cards":[{"q":"الزبير ممڤوڽاءي سيفت براني.","a":"Berani ialah salah satu kelebihan Zubair yang dinyatakan dalam buku teks.","tip":"Berani ialah salah satu kelebihan Zubair yang dinyatakan dalam buku teks.","page":"76"},{"q":"الزبير ممڤوڽاءي سمڠت برڤرجوڠ.","a":"Zubair terus berjuang bersama Rasulullah ﷺ.","tip":"Zubair terus berjuang bersama Rasulullah ﷺ.","page":"75–76"},{"q":"الزبير سڽنتياس مڽوكوڠ رسول الله ﷺ.","a":"Zubair menyokong perjuangan Rasulullah ﷺ.","tip":"Zubair menyokong perjuangan Rasulullah ﷺ.","page":"74–76"},{"q":"كيت ڤرلو ممبنتو راكن يڠ ممـڤرلوكن بنتوان.","a":"Kita dapat meneladani kesetiaan sahabat dengan membantu orang lain.","tip":"Kita dapat meneladani kesetiaan sahabat dengan membantu orang lain.","page":"76"}]},{"n":5,"title":"ابو عبيدة بن الجراح","subtitle":"Latar belakang Abu Ubaidah al-Jarrah","icon":"🏜️","cards":[{"q":"نام صحابة اين اياله ابو عبيدة بن الجراح.","a":"Nama sahabat ialah Abu Ubaidah bin al-Jarrah.","tip":"Nama sahabat ialah Abu Ubaidah bin al-Jarrah.","page":"77"},{"q":"نام بلياو ابو عبيدة عامر بن عبدالله.","a":"Buku teks menyebut nama asal beliau ialah Amir bin Abdullah.","tip":"Buku teks menyebut nama asal beliau ialah Amir bin Abdullah.","page":"77"},{"q":"ابو عبيدة براسل درڤد قورايش.","a":"Abu Ubaidah berasal daripada keturunan Quraisy.","tip":"Abu Ubaidah berasal daripada keturunan Quraisy.","page":"77"},{"q":"ابو عبيدة منجادي صحابة نبي محمد ﷺ.","a":"Abu Ubaidah ialah salah seorang sahabat Nabi Muhammad ﷺ.","tip":"Abu Ubaidah ialah salah seorang sahabat Nabi Muhammad ﷺ.","page":"77"}]},{"n":6,"title":"ڤرچوڠن ابو عبيدة","subtitle":"Jasa, akhlak dan wafat Abu Ubaidah","icon":"🏆","cards":[{"q":"ابو عبيدة سڽنتياس برأمانه.","a":"Amanah ialah sifat utama Abu Ubaidah yang dipuji oleh Rasulullah ﷺ.","tip":"Amanah ialah sifat utama Abu Ubaidah yang dipuji oleh Rasulullah ﷺ.","page":"78–79"},{"q":"ابو عبيدة توروت ممڤرجوڠكن اسلام.","a":"Abu Ubaidah turut berjuang mempertahankan Islam.","tip":"Abu Ubaidah turut berjuang mempertahankan Islam.","page":"77–79"},{"q":"ابو عبيدة براني دالم ڤڤرڠن.","a":"Keberanian ialah antara kelebihan Abu Ubaidah yang disenaraikan oleh buku teks.","tip":"Keberanian ialah antara kelebihan Abu Ubaidah yang disenaraikan oleh buku teks.","page":"79"},{"q":"ابو عبيدة ممڤيمڤين تنترا اسلام.","a":"Abu Ubaidah turut mengetuai pasukan tentera Islam.","tip":"Abu Ubaidah turut mengetuai pasukan tentera Islam.","page":"79"}]}]$sirahm3$::jsonb,$sirahg3$[{"n":1,"name":"🌿 Latar belakang Zubair bin al-Awwam","type":"clue","intro":"Baca Jawi dan pilih jawapan yang betul.","steps":[["سياڤاكه نام صحابة يڠ دچريتاكن دالم تاجوق اين؟",["الزبير بن العوام","ابو عبيدة بن الجراح","زيد بن ثابت","بلال بن رباح"],0,"Nama sahabat ini ialah Zubair bin al-Awwam.","73","🌿"],["سياڤاكه نام ايبو الزبير بن العوام؟",["خديجة بنت خويلد","صفية بنت عبد المطلب","عائشة بنت ابي بكر","فاطمة بنت محمد"],1,"Ibu Zubair ialah Safiyyah binti Abdul Muttalib.","73","🌿"],["اڤاكه هوبوڠن صفية دڠن رسول الله ﷺ؟",["انق سعودارا","انق","ايبو ساودارا","نيـنق"],2,"Safiyyah binti Abdul Muttalib ialah ibu saudara Rasulullah ﷺ.","73","🌿"],["الزبير دكنل سباڬاي سياڤا؟",["راج","فرعون","ڤڽمبه برهالا","صحابة رسول الله"],3,"Zubair merupakan salah seorang sahabat Rasulullah ﷺ.","73","🌿"],["بيلكاكه الزبير مڠانوت اسلام؟",["كتيك ماسه موده","ستله منجادي خليفَة","سماس ڤڠهوجوڠ حيات","د زمان نبي موسى"],0,"Zubair memeluk Islam ketika masih muda seperti dinyatakan dalam buku teks.","73–74","🌿"],["الزبير برأسل درڤد قوم اڤا؟",["عاد","قورايش","ثمود","بني اسرائيل"],1,"Zubair berasal daripada keluarga Quraisy.","73","🌿"]]},{"n":2,"name":"🤲 Keislaman dan kesetiaan Zubair","type":"clue","intro":"Baca Jawi dan pilih jawapan yang betul.","steps":[["الزبير ترماسوق دالم ڬولوڠن اڤا؟",["ڤڽمبه برهالا","ڤاسوقن فرعون","اورڠ اول مڠانوت اسلام","ڤمبورو هرتا"],2,"Zubair termasuk dalam golongan awal yang memeluk Islam.","73–74","🤲"],["اڤاكه سيفت الزبير كتيك مندهدڤي چابارن؟",["مڽره","ڤوتوس اسا","منچچا","تتڤ تڬوه"],3,"Zubair tetap teguh beriman walaupun menghadapi cabaran.","74","🤲"],["سياڤاكه يڠ ديبنتو اوليه الزبير؟",["رسول الله ﷺ","فرعون","نمرود","ابو لهب"],0,"Zubair membantu dan mempertahankan perjuangan Rasulullah ﷺ.","74–75","🤲"],["اڤاكه بشارة اونتوق الزبير؟",["مڽجادي ڤڽمبه برهالا","دجنجيكن شرݢ","منجادي راج مصر","مڠواساي لاوت"],1,"Buku teks menyebut Zubair termasuk sahabat yang dijanjikan syurga.","74","🤲"],["اڤاكه اساس كتبرانين الزبير؟",["ككاياءن","كسومبوڠن","ايمان كڤد الله","كدودوقن"],2,"Keimanan kepada Allah menjadi asas keteguhan Zubair.","74–75","🤲"],["اڤاكه ڤڠاجرن درڤد كستيااءن الزبير؟",["مڠوتاماكن ديري","برڬادوه","ممبڠڬا ديري","ستيا كڤد كبنرن"],3,"Kisah Zubair mengajar kita setia kepada agama dan kebenaran.","74–76","🤲"]]},{"n":3,"name":"🛡️ Jejak Perjuangan Zubair","type":"timeline","intro":"Susun empat tahap perjalanan perjuangan secara berurutan.","events":[["١","Zubair memeluk Islam ketika muda"],["٢","Zubair teguh bersama Rasulullah ﷺ"],["٣","Zubair berjuang mempertahankan Islam"],["٤","Kita mencontohi sifat berani dan setia"]]},{"n":4,"name":"⭐ Sifat terpuji dan iktibar Zubair","type":"clue","intro":"Baca Jawi dan pilih jawapan yang betul.","steps":[["سيفت ماناكه تـلادن الزبير؟",["ڤمالس","ڤناكوت","براني","دڠكي"],2,"Berani ialah salah satu kelebihan Zubair yang dinyatakan dalam buku teks.","76","⭐"],["اڤاكه يڠ منونجوقكن سمڠت الزبير؟",["ڤوتوس اسا","سومبوڠ","منجاءوهي اڬام","تروس برڤرجوڠ"],3,"Zubair terus berjuang bersama Rasulullah ﷺ.","75–76","⭐"],["الزبير مڽوكوڠ ڤرچوڠن سياڤا؟",["رسول الله ﷺ","فرعون","ابو جهل","نمرود"],0,"Zubair menyokong perjuangan Rasulullah ﷺ.","74–76","⭐"],["ماناكه تيندقن منچونتوهي اخلاق ترڤوجي؟",["مڠهينا راكن","ممبنتو راكن","ممبولـي راكن","مڽيمڤن دندم"],1,"Kita dapat meneladani kesetiaan sahabat dengan membantu orang lain.","76","⭐"],["اڤاكه سيكڤ كتيك مڠهادڤي اوجين؟",["مراڠوت","مالس براوسها","صابار","مڽالهكن اورڠ"],2,"Ketabahan para sahabat mengajar kita tidak mudah berputus asa.","74–76","⭐"],["سيفت ماناكه بايق ديعملكن دالم كهيدوڤن؟",["مڠومڤت","بخيل","چمبورو","جوجور"],3,"Beriman dan jujur dapat mencontohi akhlak baik para sahabat.","76","⭐"]]},{"n":5,"name":"🏜️ Latar belakang Abu Ubaidah al-Jarrah","type":"clue","intro":"Baca Jawi dan pilih jawapan yang betul.","steps":[["سياڤاكه نام صحابة يڠ دكنل دڠن صيفت امانه؟",["ابو عبيدة بن الجراح","الزبير بن العوام","مصعب بن عمير","سلمان الفارسي"],0,"Nama sahabat ialah Abu Ubaidah bin al-Jarrah.","77","🏜️"],["اڤاكه نام اصل ابو عبيدة؟",["عبدالله بن عباس","عامر بن عبدالله","خالد بن الوليد","زيد بن ثابت"],1,"Buku teks menyebut nama asal beliau ialah Amir bin Abdullah.","77","🏜️"],["ابو عبيدة براسل درڤد كتورونن اڤا؟",["روم","فارس","قورايش","بني اسرائيل"],2,"Abu Ubaidah berasal daripada keturunan Quraisy.","77","🏜️"],["ابو عبيدة اياله صحابة سياڤا؟",["نبي عيسى","نبي موسى","نبي إبراهيم","نبي محمد ﷺ"],3,"Abu Ubaidah ialah salah seorang sahabat Nabi Muhammad ﷺ.","77","🏜️"],["اڤاكه ڬلرن ابو عبيدة دالم حديث؟",["امين اومت","راج مصر","ڤمبينا كعبه","ڤمڤين برهالا"],0,"Rasulullah ﷺ menyebut Abu Ubaidah sebagai orang yang dipercayai dalam umat ini (Amin al-Ummah).","78","🏜️"],["اڤاكه بشارة يڠ دتريما ابو عبيدة؟",["كنعكن حوكومن","دجنجيكن شرݢ","دبوڠ دالم لاوت","مڽجادي راج"],1,"Abu Ubaidah termasuk sahabat yang dijanjikan syurga, seperti dalam buku teks.","77–78","🏜️"]]},{"n":6,"name":"🏆 Kenali Abu Ubaidah","type":"build","intro":"Padankan fakta dengan petunjuk tokoh.","slots":[["🌴","ابو عبيدة","Nama panggilan sahabat"],["💚","امين الامة","Gelaran sebagai orang dipercayai"],["⚔️","ڤرچوڠن اسلام","Peranan beliau"],["📅","١٨ هجرة","Tahun wafat beliau"]]},{"n":7,"name":"💎 BONUS — Dua Sahabat Mulia","type":"treasure","intro":"Cabaran terakhir mengenai Zubair dan Abu Ubaidah.","steps":[["بيلكاكه الزبير مڠانوت اسلام؟",["كتيك ماسه موده","ستله منجادي خليفَة","سماس ڤڠهوجوڠ حيات","د زمان نبي موسى"],0,"Zubair memeluk Islam ketika masih muda seperti dinyatakan dalam buku teks.","73–74","🌿"],["اڤاكه ڤڠاجرن درڤد كستيااءن الزبير؟",["مڠوتاماكن ديري","برڬادوه","ممبڠڬا ديري","ستيا كڤد كبنرن"],3,"Kisah Zubair mengajar kita setia kepada agama dan kebenaran.","74–76","🤲"],["اڤاكه سيفت الزبير دالم ڤرچوڠن اسلام؟",["براني","ڤناكوت","ڤمالس","بخيل"],0,"Zubair dikenali kerana keberaniannya dalam perjuangan Islam.","74–76","🛡️"],["اڤاكه يڠ منونجوقكن سمڠت الزبير؟",["ڤوتوس اسا","سومبوڠ","منجاءوهي اڬام","تروس برڤرجوڠ"],3,"Zubair terus berjuang bersama Rasulullah ﷺ.","75–76","⭐"],["ابو عبيدة براسل درڤد كتورونن اڤا؟",["روم","فارس","قورايش","بني اسرائيل"],2,"Abu Ubaidah berasal daripada keturunan Quraisy.","77","🏜️"],["ابو عبيدة ڤرنه منجادي ڤمڤين اڤا؟",["ڤڽمبه برهالا","تنترا اسلام","ڤاسوقن فرعون","پنياغا ڤاسر"],1,"Abu Ubaidah turut mengetuai pasukan tentera Islam.","79","🏆"]]}]$sirahg3$::jsonb,true)
